
/* Enable answer engine. Retrieval over this site's own pages, built at deploy time.
   No model, no backend: it finds the passage that actually answers and cites the page. */
(function(){
  var INDEX = [{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"We work every layer of the stack, from the data underneath to the agents on top.","x":"An agent is only as good as the data and the workflows beneath it. Enable builds across Data 360, Customer 360, Agentforce and AIforce, and we are honest about which layer your problem actually sits in."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Four layers. Most partners are strong at one of them.","x":"Salesforce now sells a stack rather than a product, and the usual failure mode is a partner who is excellent at the layer they came from and vague about the rest. Enable is hands-on at all four. That matters most when the fix for an agent that keeps getting things wrong turns out to be a data model two layers down."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"AIforce","x":"Claudeforce, Slackforce, Coworker and the headless toolkit: where your people actually meet the platform. We design the surfaces the work happens in, rather than assuming everyone will log into Salesforce to do their job."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Agentforce","x":"Piper, Casey, Fin, Carter and the agents you build yourself. We design, ground, guardrail and evaluate them against real cases. An agent nobody can supervise does not go to production, whatever the demo looked like."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Customer 360","x":"Sales, Service, Field, Marketing, Commerce, Revenue, Industries and Tableau. The layer that still does most of the actual work, and the one that has to be right before an agent has anything reliable to act on."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Data 360","x":"Integration, federation and harmonisation through MuleSoft, Informatica and Agent Fabric. Identity resolution, calculated insights and the semantics that make grounding work. Quietly, this is where most AI programmes come apart."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"The people you meet do the work","x":"No bench of juniors, and no handover to someone you have never spoken to. Senior practitioners from the first call through to the handover."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"We start with the business","x":"Before we open Salesforce we want to know what you are trying to do and what has already been tried. Sometimes the answer is a build. Sometimes it is a small change. Sometimes it is that Salesforce is not the tool."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"In the new capabilities since launch","x":"Data 360, Agentforce and Agentforce Marketing have been part of our practice from the day each shipped, not added to the website when the demand turned up."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Scoped honestly, priced up front","x":"Fixed scope, fixed price and fixed date wherever the work allows it. No padded hours, no surprise invoices, and nothing on the bill you cannot point to."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"We tell you what you need to hear","x":"We would rather have a useful conversation than win a project that should not have happened. That goes for scope, for timing, and for whether the platform fits at all."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"No lock-in","x":"No lock-in contracts, non-competes or minimum terms. Even Waypoint, our continuous improvement programme, runs month to month. If we are delivering, the contract will not be the reason you stay."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Where Salesforce stops, these three carry on.","x":"We implement products rather than resell them, and we only take on ones we would put into our own org. Each is native to Salesforce, so nothing here adds a second system to keep in sync. Website, eCommerce and point of sale, inside Salesforce. One catalogue and one customer record across web, counter and CRM, with no connector in between. Agreements that never leave Salesforce. Documents generated from your records, signed without an account, and filed back automatically. Built in Christchurch. The reason your team"},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Start with a build","x":"Fixed scope, fixed price, fixed date. Three to four weeks each, and each one becomes the first entry on your Waypoint backlog rather than a project that simply ends. Larger programmes run the same way, phase by phase."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Keep improving with Waypoint","x":"A standing programme of review, prioritisation and build. Every quarter we look at what the platform is actually doing, you decide what is worth changing, and we change it. Month to month, no minimum term."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Training and enablement","x":"Adoption is a people problem, not a licensing one. The measure of a good course is that you stop needing us for routine work."},{"p":"index","t":"Salesforce partner, Auckland and Wellington | Enable","h":"Let's talk about your business first.","x":"Tell us what you are trying to do. We will tell you which layer of the stack it lives in, what it would take, and whether it is worth doing at all. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Continuous improvement for a platform that does not stay finished.","x":"Waypoint is a standing programme of review, prioritisation and build. Every quarter we look at what your platform is actually doing, agree what is worth changing, and change it. Month to month, no minimum term. Four steps, repeated. Nothing enters the backlog that you have not chosen at step two."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Most Salesforce orgs peak on the day they go live.","x":"The project ends, the consultants leave, and the platform starts drifting. Fields get added without a reason. Reports multiply. Adoption slips quietly. Two years later somebody proposes a rebuild, and the business pays a second time for capability it already owned."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Nobody owns the roadmap","x":"After go-live the backlog becomes whatever was escalated most recently. Improvement stops being planned and starts being reactive."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Change without a record","x":"Fields, flows and permissions accumulate. Nobody can say why any of it is there, which makes the next change slower than the last one."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Adoption decays quietly","x":"Usage falls well before anyone reports a problem. By the time it shows up in a number, the habit has already gone."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Paid-for capability sits unused","x":"Three Salesforce releases a year ship features you are already licensed for. Without someone watching, they stay switched off."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"One loop, run every quarter","x":"The same four steps each quarter, so the platform improves on a cadence rather than whenever something breaks loudly enough."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Review","x":"We look at what the platform is actually doing: adoption by team, data quality, automation failing quietly, technical debt, and the capability in the last three releases that you are paying for and not using."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Prioritise","x":"Findings come to you with an effort estimate against each one, and you decide what is worth doing. Nothing enters the backlog that you have not chosen, and anything you decline comes off the list rather than reappearing."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Build","x":"The agreed work is built, tested and released by the same senior practitioners who reviewed it. Every change is documented as it lands, so the record is never reconstructed from memory six months later."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Measure","x":"The next review opens with what changed and what it moved. Where something did not move, we say so plainly and it comes off the list rather than being restated as a win."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"A named senior practitioner","x":"The same person every month. They learn your org properly, and you stop re-explaining it at the start of every request."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Agreed build capacity","x":"A set allocation of build days each month, spent on the backlog you prioritised. Unused days roll forward one month so a quiet period is not simply lost."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Quarterly platform review","x":"Adoption, data quality, automation health, security and technical debt, written up with findings ranked by what they are costing you rather than by how interesting they are."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Release readiness","x":"Three Salesforce releases a year, checked against your org before they land rather than after something stops working on a Monday morning."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Documentation that stays current","x":"Configuration and change documentation updated as work lands, plus a decision register with the reasoning kept alongside each decision."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Advisory access","x":"The conversation about whether something is worth doing, before it becomes a request. Often the most valuable part, and the hardest to buy by the hour."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Build something first, then keep improving it","x":"Most organisations join Waypoint by building a capability first. Each of these is fixed scope, fixed price and fixed date, and becomes the first entry on your Waypoint backlog rather than a project that simply ends."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Agentforce Pilot","x":"One production-ready agent handling one real, repetitive workflow, with guardrails."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Marketing Cloud Next Kickstart","x":"Your first Flow-driven campaign live, reaching the right person at the right time."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"How it is priced","x":"A monthly fee set by the build allocation you want, agreed before you start. Unused days roll forward one month. Change the allocation, pause, or stop, with a month's notice."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"What it does not cover","x":"Work larger than the monthly allocation is quoted as a separate fixed-price piece rather than absorbed quietly. Salesforce licence costs, third-party product support and end-user training beyond ad hoc guidance sit outside it."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Why there is no term","x":"Enable does not use lock-in contracts, non-competes or minimum terms, and Waypoint is no exception. A programme that has to be contractually enforced is not delivering. If it is worth having, the invoice will not be the reason you stay."},{"p":"waypoint","t":"Waypoint: continuous Salesforce improvement | Enable","h":"Find out what your platform is actually doing.","x":"The first platform review stands on its own. You get the findings and the estimates whether or not you carry on into Waypoint, and plenty of organisations take the report and fix things themselves. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Salesforce, built around what your business actually does.","x":"Sales Cloud, Service Cloud, Data 360, Agentforce and Agentforce Marketing, delivered by senior practitioners who ask what you are trying to do before opening the platform. What are you trying to do? Who is the work actually for? What has already been tried? What happens if nothing changes? A lot of the time the answer is not a new feature. It is a clearer view of the problem."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Five practices, one team, no handover between them.","x":"Most projects touch more than one of these, and the seams are where things usually go wrong. The same people work across all five, so the conversation about how marketing data reaches a service agent happens in the room rather than between two firms."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Sales Cloud","x":"Pipeline that matches how your team actually sells, stages that mean something, and a forecast your CFO will not laugh at. Territory, quoting and partner management where the model needs them."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Service Cloud","x":"Case management, Omni-Channel routing, knowledge and entitlements. Built so the person answering knows what they are looking at, and so the SLA reflects an actual commitment."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Data 360","x":"The single customer view you keep being told you have. Identity resolution, calculated insights, activations into everything else, and honest modelling of what the credits will cost before you commit."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Agentforce","x":"Agents doing real work: deflecting cases, supporting sellers, running the internal jobs nobody got to. Designed, grounded, guardrailed and evaluated against actual cases before anything reaches a customer."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Agentforce Marketing","x":"Marketing Cloud Next on the core platform. Audiences from Data 360, journeys built in Flow, and campaigns that do not read like a 2014 email blast. Migration from SFMC or Pardot where that is the starting point."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"And the parts around them","x":"Integration, migration, sharing and security models, Experience Cloud, Tableau, and the governance that keeps an org from turning into a museum. Rarely the headline, usually the reason a project lands."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Understand the problem","x":"Before we open Salesforce we want to know what you are trying to do, who the work is for, and what has already been tried. Sometimes the answer is a major build. Sometimes it is a small change. Sometimes it is that Salesforce is not the right tool at all, and we will say so."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Scope it honestly","x":"Fixed scope, fixed price and fixed date wherever the work allows it, agreed before anything starts. No padded hours, no surprise invoices, and nothing on the bill you cannot point to. Where genuine uncertainty exists it goes in the assumptions, not scattered through the scope."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Build it ourselves","x":"The people you meet are the people who do the work. No bench of juniors, and no handing your project to someone you have never spoken to. Senior practitioners from the first call through to the handover."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Hand it over properly","x":"Configuration documentation, change and decision registers, training material and user guides, written on the assumption you may never need to call us again. If you want to keep improving it from there, that is what Waypoint is for."},{"p":"salesforce","t":"Salesforce consultancy, Auckland and Wellington | Enable","h":"Let's talk about your business first.","x":"We would rather have a useful conversation than win a project that should not have happened. That goes for scope, for timing, and for whether the platform fits at all. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. Auckland and Wellington. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"We started Enable because we kept seeing the same problem.","x":"Good organisations with a Salesforce platform that was not doing what it should. Money had been spent and features switched on, but the work that mattered still was not getting done."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"The issue was rarely the technology.","x":"It was that nobody had started with the business. So that is where we start. Business first, Salesforce second. We want to understand what you are trying to do before we talk about how the platform fits. Sometimes the answer is a major build. Sometimes it is a small change. Sometimes it is telling you that Salesforce is not the right tool at all, which is a conversation that costs us a project and saves you one. We work across the full platform: Sales Cloud, Service Cloud, Data 360, Agentforce and Agentforce Market"},{"p":"about","t":"About Enable: business first, Salesforce second","h":"The people you meet do the work","x":"No bench of juniors. No handing your project to someone you have never spoken to. Senior practitioners from the first call through to the handover, which is also why we take on fewer projects than we could."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"We scope honestly","x":"Fixed price agreed up front, and we do the work ourselves. No padded hours, no surprise invoices, nothing on the bill you cannot point to."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"We tell you what you need to hear","x":"We would rather have a useful conversation than win a project that should not have happened. That goes for scope, for timing, and for platform fit."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"No lock-in","x":"No lock-in contracts, non-competes or minimum terms. Even Waypoint, our continuous improvement programme, runs month to month. If we are delivering, the contract will not be why you stay."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"First in the region on the new things","x":"Enable was the first partner in APAC to deliver Marketing Cloud Next, with seven implementations since. Specific and checkable beats \"extensive experience\"."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"You keep everything","x":"Configuration and change documentation, decision registers with the reasoning, training material. Written on the assumption you may never need to call us again."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"Blair Rooney","x":"Managing Director If you engage Enable, this is who you are working with. Not a sales lead who hands you over after the kick-off, and not a delivery manager reading someone else\u2019s notes."},{"p":"about","t":"About Enable: business first, Salesforce second","h":"If that is the kind of partner you are looking for, we should talk.","x":"Tell us what you are trying to do. We will tell you which layer of the stack it lives in, what it would take, and whether it is worth doing at all. Auckland and Wellington, working across New Zealand and Australia. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"Let\u2019s talk about your business first.","x":"Tell us what you are trying to do. We will tell you which layer of the stack it lives in, what it would take, and whether it is worth doing at all."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"Send us a note","x":"We reply to everything, usually the same working day. No mailing list, no drip sequence."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"A reply, usually same day","x":"From Blair, not an account manager and not an automated acknowledgement. If we are not the right people for what you are describing, that is what the reply will say."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"A conversation, not a pitch","x":"Half an hour to understand what you are trying to do, who the work is for, and what has already been tried. We will ask more questions than we answer, which is the point."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"A written recommendation","x":"Where it is warranted: what we think the work is, roughly what it costs, and what we would do first. Including the recommendation not to proceed where that is the honest answer."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"Talk to Blair directly","x":"Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. The people you meet are the people who do the work, which starts with this call."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"Where we work","x":"Auckland and Wellington, working with organisations across New Zealand and Australia. On site when it helps, remote when it does not."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"What it costs to ask","x":"Nothing. A first conversation is not a sales process, and we would rather tell you early that something is not worth doing than find out together in month four."},{"p":"contact","t":"Contact Enable | Salesforce partner, New Zealand","h":"Not sure it is even a Salesforce problem?","x":"Ask anyway. A useful conversation beats a project that should not have happened, and we are reasonably good at telling the difference early. Enable Digital. Auckland and Wellington. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Your store and your CRM should be one system. With StoreConnect, they are.","x":"Enable builds websites, online stores and point of sale natively on Salesforce. One catalogue, one customer record, one place your team already works. The arrows are not integrations. All three write to the same Salesforce record directly."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Most commerce projects finish with two systems and an expensive sync between them.","x":"The storefront goes on Shopify or WooCommerce. The customer record stays in Salesforce. Between them sits a connector, a nightly job and someone whose real job has quietly become reconciling orders. It holds together until it doesn't, and the first sign is usually a report that no longer matches the one beside it."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Two customer records","x":"Someone who buys online and again at the counter becomes two contacts, and neither history is complete."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Reports that disagree","x":"Finance, marketing and service each quote a different number, because each is reading a different system."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Integration as a running cost","x":"Middleware licences, connector upgrades and the one developer who understands them become a permanent line item."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Automation that stops at the border","x":"Salesforce cannot act on an abandoned cart, a stock hold or a warranty claim it never sees."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"StoreConnect is an AppExchange package. The store runs inside Salesforce.","x":"There is no API layer and no external database. Products, pricing, stock, orders, customers, pages and content are Salesforce records. Your admins already know how to change them, your reports already know where to find them, and your Flows can act on them the moment they are created."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Website and CMS","x":"Pages, blogs, navigation and media managed as Salesforce records, with full control of the theme, CSS and custom JavaScript. Media is served through a CDN."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"eCommerce","x":"Physical goods, digital products, events, bookings, subscriptions, memberships and donations. Promotions, loyalty points, gift cards and account credit, with no order limits."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Point of sale","x":"Card terminals, cash drawers, receipt and label printers, scanners and roving tablets, with no hardware lock-in and an offline mode that resyncs when the connection returns."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Multi-store, multi-currency","x":"Several storefronts, brands or regions on one back end, with their own pricebooks, region-based tax and shared stock. Sell in NZD and anything else at the same time."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Agentforce agents","x":"Commerce agents grounded in your own catalogue, policies and order history. They read the same records your staff do, so there is no knowledge base to retrain when a price changes."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Security and compliance","x":"SOC 2, ISO 27001, PCI DSS 4.0.1 and GDPR, on Salesforce infrastructure. One system to certify instead of three, and one less place cardholder data can sit."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"You already run Salesforce","x":"You have Sales Cloud or Service Cloud and now need to sell online, or a storefront that never properly connected to either. StoreConnect puts commerce on the records you already trust, so pipeline, cases and orders finally sit together."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"You are comparing platforms","x":"Shopify and BigCommerce will get you selling quickly. The cost turns up later, in integration work and a second set of customer data. If a single view of the customer matters more than a theme marketplace, that comparison is worth running properly. We will run it with you."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"You are a not-for-profit","x":"One-off and recurring donations, memberships, event tickets, merchandise and in-person sales, all against one supporter record. The account portal needs no Experience Cloud licences, which changes the sums considerably for a charity."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"What an Enable StoreConnect build looks like","x":"Each stage stands on its own. You can stop after the first one, and some organisations should."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Fit assessment","x":"Two weeks. We look at your catalogue, your selling model, the state of your Salesforce org and the systems StoreConnect would replace. You get a written recommendation with a real number attached, including the recommendation not to proceed where that is the right answer."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Foundation","x":"Data model, product and pricebook structure, stock, region-based tax, shipping and payment providers, and the Salesforce configuration commerce depends on. Delivered as a working store you can transact against, not a document describing one."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Storefront and point of sale","x":"Theme, content, checkout, customer portal, and the register and hardware configuration for each site. Built to your brand rather than a template with your logo dropped into it. Where Agentforce is in scope, the commerce agent is grounded and evaluated here."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Handover and support","x":"Training for the people who will run the store every day, full configuration and change documentation, and a support arrangement sized to what you actually need. The handover is written on the assumption you may never need to call us again."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"No lock-in","x":"Enable does not use lock-in contracts, non-competes or retainers. We believe in delivering a successful project: on budget, on time, and to the satisfaction of the customer. If we have done that, you will keep working with us because you want to."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"StoreConnect licensing","x":"StoreConnect charges a shared success fee on each transaction rather than a per-user licence, across three plan tiers that differ by storefront count, register count, hosting and support SLA. Volume drives the cost, not headcount, and the fee is capped per transaction. We size it with you before you commit to anything."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Enable implementation","x":"Fixed price, agreed before we start. We scope the work honestly and do it ourselves: no padded hours, no surprise invoices, and nothing on the bill you cannot point to. The fit assessment is priced separately and deliberately small, so you can stop after it without having bought a build."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Organisations already running on StoreConnect","x":"These are StoreConnect platform customers, delivered across its global partner network."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Sharp Australia","x":"Several legacy websites and servers replaced by one installation covering B2B, B2C, support referrals and admin."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Playbill","x":"Multiple merchandise stores across brands and currencies, with click and collect."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Surf Life Saving Services","x":"Course bookings, equipment sales and fundraising on one platform, with LMS integration."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Grace Cosmetics","x":"A consumer storefront with the reporting and management back end built out in Salesforce."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Do we need Experience Cloud licences?","x":"No. The customer account portal does not require them, and it works with SSO if you already run a portal of your own."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"What happens to our ERP or accounting system?","x":"It stays where it is. StoreConnect sits in Salesforce alongside the integrations you already have, and the StoreConnect ecosystem covers Xero, GoldFinch, NAO and others natively."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Can we keep our current website design?","x":"Yes. The theme is fully adjustable, with custom CSS and JavaScript, so we rebuild the front end to your existing brand rather than asking you to accept a template."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"How long does an implementation take?","x":"A single storefront on a healthy Salesforce org is a matter of weeks. Multi-store, multi-currency or point of sale rollouts take longer. The fit assessment is where you get a real date."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Does it work properly in New Zealand?","x":"Yes. Multi-currency and region-based tax are standard, several payment and shipping providers are supported, and local region hosting is available on the higher plans."},{"p":"storeconnect","t":"StoreConnect on Salesforce, NZ implementation partner | Enable","h":"Tell us what you sell, and how.","x":"A short conversation is usually enough to tell whether StoreConnect is the right answer for you. If it is not, we will say so, and point you at what is. Auckland and Wellington. Salesforce partner across Sales Cloud, Service Cloud, Data 360, Agentforce and Agentforce Marketing. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Agreements that never leave Salesforce.","x":"Enable implements Lumin Sign for Salesforce: agreements generated from your records, sent, signed and filed back against the right object, without anyone leaving the CRM or rekeying a name. The top row never leaves the platform. The bottom row is the five steps it removes."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"The agreement is the one part of the deal that leaves the CRM.","x":"Everything up to the signature lives on the record. Then someone exports to Word, retypes the client details, uploads to a signing tool, chases it by email, downloads the signed copy and drags it back into Salesforce. Each of those steps is a place for the version to drift or the file to go missing."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Details retyped, and sometimes wrong","x":"Names, entity details, amounts and dates already sit on the record. Retyping them into a template is both slow and the most common source of a document that has to be reissued."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Nobody can see where it is","x":"Once a document is out for signature it disappears from the pipeline view. The status lives in someone's inbox, and the forecast quietly stops reflecting reality."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"The signed copy ends up somewhere else","x":"A shared drive, an inbox, occasionally a laptop. When the audit or the dispute arrives, finding the executed version becomes its own small project."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Templates driven by your records","x":"Connect your Salesforce data to your contract templates once, and customer details flow into every document from then on. The document is generated from the record, so the record is always the source of truth."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Recipients sign without an account","x":"No sign-up, no password, no authentication maze between your customer and a completed agreement. The single largest cause of signing drop-off, removed."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Status on the record, automation on top","x":"Sent, viewed, signed and declined are Salesforce data, which means Flow can act on them. Stage changes, task creation, onboarding kick-off and reminders all become things the platform does rather than things a person remembers."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Encrypted, SOC 2, and filed correctly","x":"All transmission encrypted, SOC 2 compliance, full audit trail, and the executed copy filed against the right object automatically. When the audit arrives, the answer is a related list rather than a search."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"The product is the easy part. The process around it is the work.","x":"Installing a managed package takes an afternoon. Making signing a reliable step in how your business actually sells takes rather longer, and that is the part we do."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Document and template design","x":"Your agreements rebuilt as templates that pull from the record, including the conditional clauses that change by product, region or entity type."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Quote-to-signature process","x":"Where signing sits in the sales process, who approves what before it goes out, and what the platform does automatically once it comes back signed."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Automation and notifications","x":"Flows that move the stage, raise onboarding tasks, chase the reminder and tell the right person, built on the signature status rather than on someone checking."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Records, retention and handover","x":"Where executed documents are filed, who can see them, how long they are kept, and the documentation your team needs to run it without us."},{"p":"lumin","t":"Lumin Sign for Salesforce, NZ implementation partner | Enable","h":"Tell us what you send out for signature.","x":"Quotes, contracts, consent forms, engagement letters or enrolments. If it starts life on a Salesforce record, it can finish there too. A New Zealand consultancy implementing a New Zealand product. Auckland and Wellington. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Your team keeps exporting to a spreadsheet. This is why.","x":"Salesforce makes editing one record easy and editing forty records painful. Enable implements GridMate, a suite of 32 Lightning components that closes the gap: real inline editing, grids, calendars, kanban and maps, on the records you already have. The screen your team currently exports. This is the one worth rebuilding first."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Thirty-two components, aimed squarely at the reasons people leave Salesforce.","x":"Every export to Excel is a small vote against the platform, and a data quality problem waiting to happen. GridMate removes the reason for the export rather than writing a policy against it."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Grids and inline editing","x":"User Grid, Pivot Grid, List View Grid and Related List Grid. Update many fields and record types at once, with four levels of filtering, grouping and sorting."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Calendars and Gantt","x":"Multi, single and compact calendars plus a Gantt chart, for teams scheduling work against records rather than in a separate tool."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Kanban and maps","x":"Kanban boards on list views and field sets, map lists and record maps, for work that is easier to see as a board or a territory than as a table."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Layout and navigation","x":"Record cards, object timelines, dynamic tabs and accordions, and a file explorer. Related records visible and editable without switching tab."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"RevenueMate, from the same team","x":"Salesforce CPQ has entered end-of-sale, and mid-market organisations now need a path that is not a Revenue Cloud programme. RevenueMate is a Salesforce-native CPQ built by the GridMate team, aimed at exactly that gap: enterprise capability without the implementation that usually comes with it. Where this stands."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Sub-second pricing","x":"Complex quotes priced without the wait that makes sellers quote in a spreadsheet instead."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Nested bundle configurator","x":"Product configuration for real catalogues, with a customisable pricing rules engine behind it."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Margin visible while quoting","x":"Real-time margin on the quote, so discount conversations happen before approval rather than after."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Approvals, audit and signing","x":"Multi-level approval workflows, full audit trails, and vendor-agnostic e-signature. Lumin slots in here."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Components are cheap. Deciding where they belong is the work.","x":"Dropping 32 components onto every page makes an org worse, not better. We work out which views actually cause the spreadsheet exports, and fix those."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Find the actual friction","x":"We watch how your team really works and find the three or four screens where people give up and export. Those are the ones worth rebuilding."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Configure to the role","x":"A grid for a service team and a grid for a finance team are different grids. Filters, columns, permissions and record-type behaviour set per role."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Protect the data model","x":"Bulk editing is powerful in both directions. Validation, field-level security and sharing checked before anyone can change forty records at once."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Measure whether it worked","x":"Adoption before and after, and report exports tracked. If the spreadsheet habit does not fall, the change did not work and we say so."},{"p":"gridmate","t":"GridMate for Salesforce, implementation partner | Enable","h":"Which screen does your team keep exporting?","x":"Tell us that, and we can usually tell you within a call whether GridMate fixes it or whether the problem is the data model underneath. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Fundraising, programmes and the people behind both, on one platform.","x":"Agentforce Nonprofit, still widely called Nonprofit Cloud, puts giving, programme delivery, case management and outcomes on core Salesforce objects. Enable builds it around how your organisation actually works."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"What Nonprofit Cloud actually covers","x":"It is broader than fundraising, and that breadth is the point. Most nonprofits run a CRM for donors and something else entirely for the work the donations pay for. Nonprofit Cloud is the first credible Salesforce answer to having both in one place."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Fundraising","x":"Gift transactions, gift commitments for recurring giving, designations and soft credits, with donor rollups that do not need a nightly job to be trusted."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Programme management","x":"Programmes, cohorts, enrolments and service delivery, so the work the organisation actually does is a record rather than a spreadsheet beside the CRM."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Case management","x":"Client intake, assessment, referral and review for social services, with the confidentiality and sharing model that kind of data demands."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Outcome measurement","x":"Indicators, baselines and results tracked against programmes, so the impact report is generated from the data rather than reconstructed each year."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Grantmaking","x":"For funders: applications, review, award, disbursement and reporting, on the same platform as the relationships behind them."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Volunteers and supporters","x":"Volunteer roles, shifts and hours alongside the household and constituent model, so a person who gives time and money is one record, not two."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Supporters, not customers","x":"A person can be a donor, a volunteer, a service user and a board member at once. A data model built for B2B sales handles that badly, and the damage shows up in the stewardship rather than in a report."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Budget scrutiny is public","x":"Spending on systems is visible to funders and sometimes to media. Complimentary discovery, capped fees and paying only for days used are not niceties here, they are how the decision gets defended internally."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"The mission argument is real","x":"Better supporter data means more money reaching the cause and less staff time on reconciliation. We will make that connection once, with numbers, and then get on with the build."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Constituent and household modelling","x":"How people, households, organisations and relationships are represented, decided before anything is built. Almost every painful nonprofit implementation traces back to this being settled late."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Fundraising process design","x":"Gift entry, recurring giving, designations, soft credits, acknowledgement and receipting, built to your actual finance process rather than to a reference diagram."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Programmes, cases and outcomes","x":"The delivery side modelled properly, including the sharing and confidentiality rules that client data in social services requires. This is where most partners stop and we do not."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Licensing and the Power of Us discount","x":"Working out what you are actually entitled to, what the ten donated licences do and do not cover, and what the real annual cost looks like before you commit."},{"p":"nonprofit","t":"Nonprofit Cloud consultants, New Zealand | Enable","h":"Tell us who your supporters are.","x":"How you model people, households and giving decides most of what follows. It is worth an hour before anyone opens a builder. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Moving from the Nonprofit Success Pack to Nonprofit Cloud.","x":"NPSP remains supported and Salesforce has announced no forced end date. That makes this a decision rather than a deadline, which is the best possible time to make it carefully. Start with an assessment, not a migration plan. The model underneath is different, which is why this is a rebuild rather than a data load."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Where we stand on this","x":"Enable has years of Salesforce nonprofit experience and delivers Nonprofit Cloud today. NPSP migration is an offering we are bringing to market now, rather than a decade-long track record we are going to claim. What that means in practice: the assessment is priced small and sold on its own, the findings are yours whether or not you continue, and we will tell you plainly where the ground is new for everyone."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"The first question is whether to move at all","x":"Plenty of organisations are running NPSP well and should keep doing so for now. The cost of moving is real, and a migration undertaken because of a rumour about end-of-life is a migration done for the wrong reason."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Reasons to move now","x":"You need programme, case or outcome management and are currently bolting it on. You are buying new Salesforce capability that assumes core objects. Your customisation of NPSP has become the thing that blocks every upgrade."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Reasons to wait","x":"NPSP is doing what you need, your customisation is light, and the money would do more good spent on the mission this year. Waiting is a legitimate answer and we will give it where it is the right one."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Reasons it is not the real problem","x":"If reporting is wrong, adoption is poor or data quality is bad, those follow you across. A migration is an expensive way to discover that the problem was the process. We would rather find that first."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"What actually changes","x":"Not a rename. The data model underneath is different, which is why a migration is a rebuild of your fundraising operation rather than a data load."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Three weeks, fixed price","x":"Priced small and deliberately separate, so you can stop after it without having bought a migration."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"What we look at","x":"Your NPSP customisation, data volumes and quality, integrations, reporting, recurring giving setup, and what your team actually uses day to day."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"What you get","x":"A written recommendation with a real number: move, wait, or fix something else first. Plus a sequenced plan if the answer is move, and the findings to act on yourself if it is not."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Model first, migrate second","x":"Constituents, households, designations and recurring giving modelled in a sandbox and tested against your real data before anything is committed. The model is the migration."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Run in parallel where it is possible","x":"Financial year boundaries, appeal cycles and audit periods decide the cutover, not the project plan. Where a parallel period is feasible we use it."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"History, receipting and the audit trail","x":"Gift history, acknowledgements and the numbers your auditor and your funders rely on, reconciled before cutover rather than explained afterwards."},{"p":"npsp-migration","t":"NPSP to Nonprofit Cloud migration | Enable","h":"Start with the question, not the migration.","x":"Tell us what is not working in NPSP today. Often the answer is a fix rather than a move, and that is a much cheaper conversation to have first. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Marketing Cloud Next, from the first partner in APAC to deliver it.","x":"Campaigns on the core platform: audiences from Data 360, journeys built in Flow, and measurement that does not need a separate warehouse. We were first in the region to ship it and have been through seven implementations since. Audience, journey, send, branch and reply all in one org. The report does not begin with an export."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"What it is, as a product","x":"Marketing Cloud Next is not the old Marketing Cloud with a new badge. It runs on the core platform, which changes what a campaign can see and what it can trigger."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Journeys built in Flow","x":"The same Flow your admins already know, not a separate journey canvas with its own logic and its own outages. A journey can call anything the platform can do."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Content and channels","x":"Branded email and content on the platform, plus SMS, WhatsApp and push. Sender setup, templates and reusable content blocks that marketers maintain themselves."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Segments from Data 360","x":"Audiences built on the unified profile rather than on a list someone exported. Membership updates as the data does, so a segment is a rule, not a snapshot."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Agentforce inside the campaign","x":"Agents that answer the reply, qualify the response and pick up the conversation the campaign started, grounded in the same records."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Data 360, the audience layer","x":"Identity resolution, unified profiles and calculated insights. A segment is only ever as good as the resolution underneath it, and most campaigns that misfire, misfire here rather than in the creative. We model the credits before you commit, because consumption is where these programmes get expensive."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Personalisation, the moment","x":"Real time means acting on behaviour as it happens: a browse, an abandoned form, a change in the profile. Not a list assembled three weeks after the moment has passed. This is the difference between personalisation and a mail merge, and it is the reason the platform sits where it does."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Intelligence, the measurement","x":"Engagement scoring, Einstein assists and attribution that runs back to pipeline or to giving in the same org. Because it is one platform, the report does not begin with an export, which is usually where marketing measurement quietly stops being trusted."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Migrating from Marketing Cloud Engagement or Pardot","x":"Most estates we look at carry a decade of journeys, half of which nobody has switched off. The migration is an opportunity to stop running those, and the plan should say so out loud."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Decide what actually moves","x":"An inventory of every journey, automation and send, with an owner and a last-run date against each. A surprising amount of it gets retired rather than rebuilt, and that is the cheapest win available."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Data and consent before anything else","x":"Subscriber data, preference centres, consent records and suppression lists reconciled first. Getting consent wrong in a migration is the one mistake with a regulator attached to it."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Deliverability and authentication","x":"SPF, DKIM, DMARC, sending domains and IP warm-up planned before the first production send. Sending reputation takes months to build and one bad weekend to lose."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"Parallel run, then switch","x":"Both platforms live, results compared on real sends, then cut over. We do not do big-bang marketing migrations, and we will not lift a broken journey across so it can keep being broken."},{"p":"marketing-cloud-next","t":"Marketing Cloud Next, first APAC partner | Enable","h":"What are you sending today, and what is it doing?","x":"Bring the journey inventory if you have one. If you do not, that is usually the first thing worth building, and it is often where the business case comes from. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work","t":"Our work, described honestly | Enable","h":"The work, described honestly.","x":"Four engagements, written up without the numbers we cannot verify and without the client names we have not been given permission to use. What is here is what was actually built and what it actually changed. We will introduce you to a client who will talk to you. That is worth more than a logo wall."},{"p":"work","t":"Our work, described honestly | Enable","h":"Six systems, one supporter","x":"A supporter who joins, gives, visits a property and buys in the shop was five records in five places. Unified on Data 360, in production."},{"p":"work","t":"Our work, described honestly | Enable","h":"Every enquiry reached one person","x":"Strong enquiry volume, all landing in one consultant\u2019s queue because of a routing fallback nobody had revisited since go-live."},{"p":"work","t":"Our work, described honestly | Enable","h":"Agri-tech, on Salesforce","x":"Farm financial software for New Zealand and Australian farmers. Engagement detail to come."},{"p":"work","t":"Our work, described honestly | Enable","h":"Teams that ship faster, with AI in the loop","x":"Rapid AI-assisted development practice stood up with their teams, so delivery moves at a different pace and the capability stays in-house."},{"p":"work","t":"Our work, described honestly | Enable","h":"Why only one client is named","x":"Heritage New Zealand, Real Living and Hato Hone St John are named with their agreement. Farm Focus is still a draft, and putting a client\u2019s name on a marketing page without asking is a strange way to demonstrate that you can be trusted with their data. As each one says yes, their name goes up. Until then the work is described accurately and the organisation is not identified. Ask us and we will put you on a call with someone who has worked with us."},{"p":"work","t":"Our work, described honestly | Enable","h":"Want to talk to one of them?","x":"We will make the introduction. No sales call in between, and you can ask them whatever you like, including what went wrong. Blair Rooney, Managing Director. blair@enabledigital.co, +64 22 226 4252. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Heritage New Zealand can see the whole relationship, not a fragment of it.","x":"A supporter who joins, gives, visits a property, books an event and buys something in the shop used to be five records in five places. Enable unified them on Data 360 and put the resulting profile in front of the people who need it, in production."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"The organisation","x":"Heritage New Zealand Pouhere Taonga is the Crown entity responsible for identifying, protecting and promoting New Zealand\u2019s historic places. It cares for properties the public visits, maintains the national list of heritage places, and is supported by members, donors and volunteers. That breadth is the interesting part. The same person might hold a membership, give to an appeal, walk through a property on a Sunday, book a school visit, send an enquiry about a listing, and buy a book in the shop. Six relationships, "},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"The situation","x":"Every one of those interactions was being recorded. None of them were being recorded together. Answering a question as ordinary as \u201chas this person supported us before\u201d meant opening several systems and making a judgement call about whether three similar-looking records were the same person. Everyone knew this. What did not exist was a route through it that began with a multi-year data warehouse programme, which for a Crown entity with public funding is a hard thing to justify and a harder thing to finish."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Modelled to the standard data model","x":"Source systems mapped onto the Customer 360 data model rather than a bespoke schema. That decision is unglamorous and it is the one that decides whether the thing still makes sense to the next person who touches it, or needs remapping every time a source changes."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Ingestion and harmonisation in Data 360","x":"Memberships, donations, event bookings, property visits, enquiries and retail brought into Data 360 and harmonised, so that a date is a date and a person is a person regardless of which system spelled it which way."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Identity resolution tuned against real records","x":"A ruleset built and tested on the actual data, including households, shared email addresses, and people who have been in the database since the nineties under three spellings of the same name. Match results were reviewed with staff who know the constituents, not signed off against a metric."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Unified profile activity","x":"The engagement history brought together so a single view shows what a person has actually done, in order, regardless of which system recorded it. This is the part users notice, and the part that makes the rest of the work legible to people who were never going to read a data model."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Surfaced where the work happens","x":"The unified profile exposed on the records staff already use, rather than in a separate analytics tool nobody opens. A capability that requires a second login is a capability that gets used twice."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Deployed to production, with tests","x":"Apex covered per class and deployed against the production org with specified tests, not left as a sandbox proof of concept for someone to productionise later. Production is where this either works or does not."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"The question is answerable","x":"\u201cHave we talked to this person before, and about what?\u201d is now one screen instead of three people checking three systems and comparing notes in a meeting."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Data quality became visible","x":"Resolution surfaces the duplicates everyone suspected and nobody could count. That is uncomfortable and useful in roughly equal measure, and it gives the next cleanup an actual target."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"A foundation, not an endpoint","x":"Segmentation, agent grounding and personalisation all need a resolved profile underneath them. Building it first makes every one of those conversations shorter, and cheaper."},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"What we would tell you","x":"Identity resolution is where this kind of project succeeds or quietly fails, and it cannot be done well from a spreadsheet of field mappings. Budget real time for sitting with the people who know the constituents. They will spot a bad match in a second that a rule would have accepted forever. Data 360 consumption is real money. We would rather model it with you before you commit than explain the bill afterwards, and for a publicly funded organisation that conversation needs to happen in writing, early. And a produc"},{"p":"work-heritage","t":"Case study: six systems, one supporter profile | Enable","h":"Recognise any of this?","x":"If your supporters turn up in six systems and none of them agree, the first conversation is free and usually tells us both whether there is a project here. Published with Heritage New Zealand Pouhere Taonga\u2019s agreement. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Every enquiry was reaching the same person.","x":"Real Living was generating strong enquiry volume across several villages. Almost all of it was landing in one consultant\u2019s queue, because of a routing fallback nobody had revisited since go-live. The rules read correctly. A fallback written as a safety net had become the main path."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"The situation","x":"Marketing was working. Enquiries were arriving. But follow-up was slow and uneven, and leadership could not see why. The routing rules looked correct on paper. What had happened was more ordinary: a fallback assignment, written as a safety net at go-live, had quietly become the main path, because several village-level users had been deactivated over the years and duplicates created in their place. Every enquiry that failed to match an active user fell through to the same queue and the same person."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Traced the routing, not the symptom","x":"The reported problem was slow follow-up. The actual problem was assignment. We followed real enquiries through the rules rather than reading the configuration and assuming it did what it said."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Rebuilt assignment around the village","x":"Routing keyed to the village the person is enquiring about, with an owner per village and a fallback that alerts somebody rather than silently absorbing the work."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Cleaned up the user estate","x":"Inactive users and their duplicates identified and resolved, which is unglamorous and was the actual root cause."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Made tours visible on the account","x":"Tour bookings were being recorded against a child object that the account page never showed, so a booked visit was invisible to anyone looking at the person. We surfaced it, and fixed a re-entrant save loop found along the way."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Enquiries reach the right village","x":"Follow-up is now done by the person who knows the site the enquirer is asking about, which changes the quality of the conversation as much as the speed."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"One consultant got their week back","x":"The person absorbing the fallback was carrying work that was never meant to be theirs, and no report showed it."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Leadership can see the funnel","x":"Enquiry through to tour through to outcome, per village, from records rather than from a manually maintained spreadsheet."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"What we would tell you","x":"Nobody had done anything wrong here. A sensible safety net at go-live became the default path over several years of ordinary staff turnover, and no report was looking at assignment. It is worth someone checking routing fallbacks annually, which is exactly the kind of thing a quarterly platform review catches."},{"p":"work-retirement-living","t":"Case study: when every enquiry reaches one person | Enable","h":"Recognise any of this?","x":"If it sounds like your org, the first conversation is free and usually tells us both whether there is a project here. Client withheld pending consent. Happy to make an introduction on request. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work-farm-focus","t":"Case study: Farm Focus | Enable","h":"[HEADLINE: what changed for Farm Focus]","x":"[ONE PARAGRAPH: what Enable did and what it made possible. Everything on this page below the organisation section is waiting on the engagement detail. Tell me what the work was and this gets written properly.] The organisation section below is researched and accurate. The rest needs you."},{"p":"work-farm-focus","t":"Case study: Farm Focus | Enable","h":"The organisation","x":"Farm Focus makes farm financial management software for New Zealand and Australian farmers and growers: cashflow planning, GST returns, livestock reconciliation and reporting, in one place. It began in 1981 when three Wairarapa farmers wanted a better way to forecast a farm business, and the product that came out of it, Cash Manager, ran for forty years before the company rebranded to Farm Focus in 2021. It is based in Masterton and serves thousands of customers across sheep, beef and dairy, from single operators t"},{"p":"work-farm-focus","t":"Case study: Farm Focus | Enable","h":"This page is unfinished","x":"The organisation section above is researched from public sources and accurate. Everything else is a placeholder, because inventing work Enable did for a named New Zealand company is the one mistake this page cannot recover from. What is needed: what the engagement actually was, which part of the platform it touched, roughly when, and what changed as a result. Four sentences is enough to write the rest. Until then this page should stay unpublished and its card removed from the index."},{"p":"work-farm-focus","t":"Case study: Farm Focus | Enable","h":"[CTA HEADLINE]","x":"[One or two sentences inviting the reader with a similar problem to get in touch.] Draft. Not for publication until the engagement detail is confirmed. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Building teams that ship faster, with AI in the loop.","x":"Hato Hone St John wanted delivery to move at a different pace. Enable worked with their teams to stand up rapid AI-assisted development practice: not a tool rollout, but a way of working that gets from idea to something running in a fraction of the time. The grey row is a number only Hato Hone St John can give us. Everything above it is checkable."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"The organisation","x":"Hato Hone St John has been operating in New Zealand since 1885. It is a charity, it employs and enrols many thousands of paid staff and volunteers, and it provides the overwhelming majority of the country\u2019s emergency and non-emergency ambulance coverage, alongside first aid training, event medical cover, community health programmes and support lines for people living alone. That is a wide operational surface, and it is one where software delays have a cost that is not measured in revenue. Technology that takes eigh"},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"The situation","x":"The teams were capable and the backlog was longer than the delivery capacity, which is the ordinary condition of almost every in-house technology function. The question was not whether people were working hard. It was whether the way work moved from idea to running software could be changed at all, rather than simply resourced harder. AI tooling was the obvious lever and also the obvious trap. Handing a team a licence and calling it transformation is how most organisations spend a year discovering nothing changed."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Started with how work actually moves","x":"Before any tooling, we followed real work through the current process: where it waited, where it was rewritten, where a decision took three weeks because the right four people were never in the same conversation. Speed problems are usually queueing problems wearing a technical costume."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Stood up rapid development teams","x":"Small teams set up to go from a stated problem to something running, with AI assistance built into the loop rather than bolted on at the coding step. Scoping, drafting, reviewing and testing all change when the cost of a first version falls."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Built the judgement, not just the habit","x":"The hard part of AI-assisted delivery is knowing when to trust the output and when not to. We worked on review practice, on what gets checked and by whom, and on where a human has to stay in the loop regardless of how convincing the draft looks."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Left the capability with their teams","x":"The measure of this work is that it keeps going without us. Practice documented, patterns written down, and the people who will run it afterwards involved from the first week rather than briefed at the end."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"From idea to running, faster","x":"The gap between someone describing a need and someone using the result closed materially. That shift compounds: shorter cycles mean more attempts, and more attempts mean better answers."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Fewer things waiting","x":"A lot of the gain was not in writing code faster. It was in the queue before the code, where work sat waiting on a decision, a spec or a review."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"The teams own it","x":"The practice sits with Hato Hone St John, not with a partner they have to re-engage to keep it running. That was the point of the engagement rather than a nice side effect."},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"What we would tell you","x":"Rapid AI development is a ways-of-working change that happens to involve tools. Organisations that buy the tools and skip the working practice get a faster first draft and the same delivery date, because the bottleneck was never typing. Review discipline matters more, not less. When output is cheap and plausible, the scarce thing is the judgement to reject it. Build that explicitly or it will not happen. And in an organisation where the work is clinical and operational rather than commercial, \u201cmove fast\u201d needs a cl"},{"p":"work-st-john","t":"Case study: rapid AI delivery at Hato Hone St John | Enable","h":"Delivery not moving at the pace you need?","x":"If your teams are capable and the backlog still grows, the constraint is usually in how work moves rather than how hard people work. That is a conversation worth having. Published with Hato Hone St John\u2019s agreement. A Salesforce consultancy in Auckland and Wellington, working across every layer of the stack."}];
  var STOP = {the:1,a:1,an:1,and:1,or:1,of:1,to:1,in:1,on:1,for:1,with:1,is:1,are:1,was:1,be:1,do:1,does:1,
    we:1,you:1,i:1,it:1,that:1,this:1,what:1,how:1,can:1,should:1,our:1,your:1,my:1,at:1,as:1,by:1,from:1,
    have:1,has:1,will:1,would:1,if:1,about:1,me:1,us:1,they:1,there:1,their:1,but:1,not:1,so:1,any:1};

  function toks(str){
    return (str||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/)
      .filter(function(w){ return w && w.length>2 && !STOP[w]; })
      .map(function(w){ return w.replace(/(ies)$/,'y').replace(/(es|s)$/,''); });
  }

  var DF = {}, N = INDEX.length;
  INDEX.forEach(function(e){
    var seen = {};
    toks(e.h+' '+e.x).forEach(function(w){ if(!seen[w]){ seen[w]=1; DF[w]=(DF[w]||0)+1; } });
  });
  function idf(w){ return Math.log(1 + N/(1+(DF[w]||0))); }

  function search(q){
    var qt = toks(q); if(!qt.length) return [];
    return INDEX.map(function(e){
      var h = toks(e.h), x = toks(e.x), ttl = toks(e.t + ' ' + e.p), sc = 0, hit = 0;
      qt.forEach(function(w){
        var inT = ttl.indexOf(w)>=0 ? 1 : 0;
        var inH = h.indexOf(w)>=0 ? 1 : 0;
        var n = 0; for(var i=0;i<x.length;i++) if(x[i]===w) n++;
        if(inT || inH || n){
          hit++;
          // square the idf so a distinctive word like "waypoint" outweighs "actually"
          sc += Math.pow(idf(w), 2) * (inT*4 + inH*3 + Math.min(n,3));
        }
      });
      // answering half the question is worth less than half as much
      return {e:e, s:sc * Math.pow(hit/qt.length, 2)};
    }).filter(function(r){ return r.s > 0; })
      .sort(function(a,b){ return b.s-a.s; }).slice(0,3);
  }

  function snippet(text, q){
    var qt = toks(q);
    var sents = text.split(/(?<=[.!?])\s+/);
    var best = sents[0], bestScore = -1;
    sents.forEach(function(sn){
      var t = toks(sn), sc = 0;
      qt.forEach(function(w){ if(t.indexOf(w)>=0) sc++; });
      if(sc > bestScore){ bestScore = sc; best = sn; }
    });
    var i = sents.indexOf(best);
    return sents.slice(i, i+2).join(' ').trim();
  }

  function el(tag, cls, txt){ var n=document.createElement(tag); if(cls) n.className=cls; if(txt) n.textContent=txt; return n; }

  var STAR = '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">'
    + '<path d="M12 2l1.9 6.1L20 10l-6.1 1.9L12 18l-1.9-6.1L4 10l6.1-1.9z"/></svg>';

  function thinking(root){
    var box = el('div','agent-think');
    var stars = el('span','agent-stars'); stars.innerHTML = STAR+STAR+STAR;
    var label = el('span',null,'Reading the site');
    box.appendChild(stars); box.appendChild(label); root.appendChild(box);
    root.scrollTop = root.scrollHeight;
    var lines = ['Reading the site','Finding the passage','Checking what it says'], i = 0;
    var t = setInterval(function(){ i++; if(i<lines.length) label.textContent = lines[i]; }, 620);
    return function(){ clearInterval(t); box.remove(); };
  }

  function followUp(root, asked){
    if(root.querySelector('.agent-followup')) return;
    var box = el('div','agent-followup');
    box.appendChild(el('p',null,'Did that answer it? If you would rather talk it through, leave your details '
      + 'and Blair will come back to you. He replies to everything.'));
    var f = document.createElement('form');
    f.style.cssText = 'display:flex;flex-direction:column;gap:12px';
    [['name','Your name','text'],['email','Email','email']].forEach(function(spec){
      var w = el('div','agent-f-field');
      var l = el('label',null,spec[1]); l.setAttribute('for','af-'+spec[0]);
      var inp = document.createElement('input');
      inp.id='af-'+spec[0]; inp.name=spec[0]; inp.type=spec[2]; inp.required=true; inp.autocomplete=spec[0];
      w.appendChild(l); w.appendChild(inp); f.appendChild(w);
    });
    var w3 = el('div','agent-f-field');
    var l3 = el('label',null,'What are you trying to do?'); l3.setAttribute('for','af-message');
    var ta = document.createElement('textarea'); ta.id='af-message'; ta.name='message'; ta.value = asked || '';
    w3.appendChild(l3); w3.appendChild(ta); f.appendChild(w3);
    var send = el('button','agent-f-send','Send it to Blair'); send.type='submit'; f.appendChild(send);
    var no = el('button','agent-f-no','No thanks, just browsing'); no.type='button';
    no.addEventListener('click', function(){ box.remove(); }); f.appendChild(no);

    f.addEventListener('submit', function(e){
      e.preventDefault();
      // f.name is the form's own name attribute, not the input - go through elements
      var data = new URLSearchParams({ 'form-name':'enable-drawer', name:f.elements.name.value,
                                       email:f.elements.email.value, message:f.elements.message.value,
                                       asked:asked||'' });
      send.disabled = true; send.textContent = 'Sending…';
      fetch('/', {method:'POST', headers:{'Content-Type':'application/x-www-form-urlencoded'}, body:data.toString()})
        .then(function(){ box.innerHTML='';
          box.appendChild(el('p',null,'That is with Blair. He replies to everything, usually the same working day.')); })
        .catch(function(){ box.innerHTML='';
          var pEl=el('p',null,'That did not send. Email blair@enabledigital.co and it will get there.');
          box.appendChild(pEl); });
    });
    box.appendChild(f); root.appendChild(box); root.scrollTop = root.scrollHeight;
  }

  function respond(q){
    var root = document.getElementById('agent-root');
    var intro = root.querySelector('.agent-prompts'); if(intro) intro.remove();
    var card = root.querySelector('.agent-card'); if(card) card.remove();
    var msg = root.querySelector('.agent-msg'); if(msg) msg.remove();

    root.appendChild(el('p','agent-you', q));
    var i0 = document.querySelector('.agent-input'); if(i0) i0.value = '';
    var done = thinking(root);
    var hits = search(q);
    // a considered pause: the answer is ready instantly, but arriving instantly reads as a lookup
    setTimeout(function(){ done(); paint(q, hits, root); }, 900 + Math.min(hits.length,3) * 220);
  }

  function paint(q, hits, root){
    if(!hits.length || hits[0].s < 2.5){
      var miss = el('div','agent-answer');
      miss.appendChild(el('p','agent-msg',
        'I cannot find that on this site, and I would rather say so than guess. Blair will know.'));
      var a = el('a','agent-cite','Ask him directly'); a.href='contact.html';
      miss.appendChild(a); root.appendChild(miss);
    } else {
      hits.slice(0,2).forEach(function(hit){
        var box = el('div','agent-answer');
        box.appendChild(el('div','agent-answer-h', hit.e.h));
        box.appendChild(el('p','agent-msg', snippet(hit.e.x, q)));
        var a = el('a','agent-cite', 'Read it on ' + hit.e.t.split('|')[0].split(':')[0].trim());
        a.href = hit.e.p + '.html';
        a.target = '_blank'; a.rel = 'noopener';   // keep the drawer alive behind the page they opened
        a.addEventListener('click', function(){ setTimeout(function(){ followUp(root, q); }, 1200); });
        box.appendChild(a);
        root.appendChild(box);
      });
    }
    root.scrollTop = root.scrollHeight;
  }

  if(window.EnableAgent) window.EnableAgent.on(respond);
  window.EnableAgent.answer = respond;
})();
